const MARKUP = "\n  <a class=\"skip-link\" href=\"#main\">Skip to content</a>\n  <header class=\"site-header\">\n    <div class=\"header-inner\">\n      <!-- Replace this text wordmark with the approved logo when supplied. -->\n      <a class=\"wordmark\" href=\"#home\" aria-label=\"The Fibroid Fixer home\">The Fibroid Fixer<span class=\"wordmark-dot\" aria-hidden=\"true\">.</span></a>\n      <button class=\"menu-toggle\" aria-expanded=\"false\" aria-controls=\"navigation\">Menu <span aria-hidden=\"true\">＋</span></button>\n      <nav id=\"navigation\" aria-label=\"Main navigation\">\n        <a href=\"#program\">Program</a><a href=\"#about\">About</a><a href=\"#expect\">What to Expect</a><a href=\"#foundations\">Foundations</a><a href=\"#faq\">FAQ</a>\n        <a class=\"button button-small button-navy\" href=\"#classes\">Register for a Class <span aria-hidden=\"true\">↗</span></a>\n      </nav>\n    </div>\n  </header>\n\n  <main id=\"main\">\n    <section id=\"home\" class=\"hero\">\n      <div class=\"hero-grid wrap\">\n        <div class=\"hero-copy\">\n          <p class=\"eyebrow\"><span class=\"small-sun\" aria-hidden=\"true\"></span> A new horizon in well-being</p>\n          <h1>Healing<br> still <span>happens.</span></h1>\n          <p class=\"hero-description\">Ancient practices. A fresh perspective.<br> Explore Qigong-based wellness education with Brother Long, created for women navigating life with fibroids.</p>\n          <div class=\"hero-actions\"><a class=\"button button-yellow\" href=\"#classes\">Register for a Class <span aria-hidden=\"true\">↗</span></a><a class=\"text-link\" href=\"#program\">Explore the program <span aria-hidden=\"true\">↓</span></a></div>\n          <p class=\"hero-note\"><span class=\"live-dot\" aria-hidden=\"true\"></span> Live on Zoom <span class=\"note-divider\" aria-hidden=\"true\"></span> Guided by Brother Long</p>\n        </div>\n        <div class=\"horizon-art\" aria-hidden=\"true\">\n          <div class=\"orbit orbit-outer\"></div><div class=\"orbit orbit-inner\"></div>\n          <div class=\"sun-disc\"></div><div class=\"sun-halo\"></div>\n          <div class=\"cloud cloud-one\"></div><div class=\"cloud cloud-two\"></div>\n          <div class=\"horizon-rule\"><span></span><span></span></div>\n          <div class=\"water\"><i></i><i></i><i></i><i></i><i></i></div>\n          <span class=\"art-axis axis-top\">BALANCE</span><span class=\"art-axis axis-bottom\">A little space. A new beginning.</span>\n          <span class=\"axis-cross\">＋</span>\n        </div>\n      </div>\n      <div class=\"hero-foot wrap\"><span>ROOTED IN TRADITION. OPEN TO POSSIBILITY.</span><a href=\"#program\">Discover the approach <span aria-hidden=\"true\">↓</span></a></div>\n    <div class=\"section-wave wave-bottom\" aria-hidden=\"true\"><svg viewBox=\"0 0 1440 100\" preserveAspectRatio=\"none\"><path d=\"M0 35C250 98 440 -12 720 30S1200 96 1440 30V100H0Z\"/></svg></div></section>\n\n    <section class=\"traditions wrap\" aria-labelledby=\"traditions-heading\">\n      <div class=\"traditions-heading\"><p class=\"eyebrow\">The traditions behind the practice</p><h2 id=\"traditions-heading\">Different paths.<br> A shared intention.</h2></div>\n      <div id=\"tradition-list\" class=\"tradition-list\"></div>\n    </section>\n\n    <section id=\"program\" class=\"program section-space\">\n      <div class=\"wrap\">\n        <div class=\"section-intro\"><div><p class=\"eyebrow\">01 / The program</p><h2>Reconnect with<br> your own practice.</h2></div><p>The Fibroid Fixer brings together three traditions in a learning-centered approach to well-being. Get to know the practices, then explore them through live classes.</p></div>\n        <div id=\"practice-list\" class=\"practice-list\"></div>\n        <div class=\"program-foot\"><span class=\"balance-symbol\" aria-hidden=\"true\">☯</span><p>Space to learn. Room to explore. A practice to make your own.</p><a class=\"text-link\" href=\"#expect\">How it works <span aria-hidden=\"true\">↗</span></a></div>\n      </div>\n    <div class=\"section-wave wave-bottom\" aria-hidden=\"true\"><svg viewBox=\"0 0 1440 100\" preserveAspectRatio=\"none\"><path d=\"M0 35C250 98 440 -12 720 30S1200 96 1440 30V100H0Z\"/></svg></div></section>\n\n    <section id=\"expect\" class=\"expect section-space wrap\">\n      <div class=\"section-intro\"><div><p class=\"eyebrow\">02 / What to Expect</p><h2>Your first class,<br> one step at a time.</h2></div><p>From signing up to joining Brother Long online, here is the planned path to your first session.</p></div>\n      <ol class=\"steps\">\n        <li><span class=\"step-number\">01</span><h3>Register</h3><p>Choose a live class when the schedule and registration become available.</p></li>\n        <li><span class=\"step-number\">02</span><h3>Complete your intake</h3><p>Registered participants will receive the pre-class survey before their first session.</p></li>\n        <li><span class=\"step-number\">03</span><h3>Receive your Zoom details</h3><p>Your Zoom information will be provided after registration.</p></li>\n        <li><span class=\"step-number\">04</span><h3>Join the live session</h3><p>Meet Brother Long online to learn and practice together.</p></li>\n      </ol>\n    </section>\n\n    <section id=\"about\" class=\"about section-space\">\n      <div class=\"wrap about-grid\">\n        <div class=\"portrait-placeholder\"><div class=\"portrait-orbit\" aria-hidden=\"true\"></div><div class=\"portrait-sun\" aria-hidden=\"true\"></div><img class=\"portrait-photo\" src=\"assets/brother-long.webp\" alt=\"Brother Long smiling, wearing a white tunic with gold embroidery\" width=\"900\" height=\"1150\" loading=\"lazy\"><div class=\"portrait-fade\" aria-hidden=\"true\"></div><div class=\"portrait-caption\"><span>Your guide</span><strong>Brother Long</strong></div></div>\n        <div class=\"about-copy\"><p class=\"eyebrow\">03 / Meet your guide</p><h2>Brother Long.<br> A shared belief<br> in possibility.</h2><p class=\"about-statement\">“What happens for others can happen for us. Multiculturalism makes us aware of what happens.”</p><p class=\"quote-credit\">— Brother Long</p><div class=\"bio\"><p>Brother Long’s journey into Qigong and holistic health began nearly two decades ago after returning home to Ohio from New York City, where he had spent a year living in the homeless shelter system. Upon his return, he participated in an African-centered Rites of Passage designed to help him transition into manhood. After a year of striving and achievement, he earned the name “Brother” Long.</p><p>It was during his Rites of Passage that Brother Long met Dr. Frost, the man who would become his teacher and introduce him to an entirely different understanding of health and the human body. Under his mentorship, Brother Long studied Esoteric Taoism, Qigong, allopathic medicine, homeopathic medicine, naturopathic medicine, Traditional Chinese Medicine and medical research. Through the people he met during this time, he was also introduced to Reiki.</p><details class=\"bio-more\"><summary><span class=\"bio-open\">Read his full story</span><span class=\"bio-close\">Show less</span> <span aria-hidden=\"true\">↓</span></summary><p>One day, Dr. Frost gave Brother Long a medical journal titled <em>Scientific Investigations into Chinese Qigong</em>. Inside was information about the Huaxia Zhineng Qigong Rehabilitation Center in China, sometimes referred to as the Medicine-less Hospital. What he read stayed with him. For the next 18 years, Brother Long continued searching for a deeper understanding of what had taken place there and how seemingly impossible changes in the human body could occur through Qigong.</p><p>That search eventually took him to Xi’an, China, where he trained in the Big Qi Field with teachers connected to the original Huaxia Zhineng Qigong Rehabilitation Center. Brother Long was the only American in his class. His training included learning the principles and practices used within this tradition of Qigong and demonstrating his ability to work with Qi, including an exercise in which he cut a cucumber in half and worked to facilitate its reconnection.</p><p>After completing his training in China, Brother Long returned to Africa in September 2026. Shortly afterward, he met Sister Sonia, and the two began working together to bring this healing wisdom to people in the United States.</p><p>Their first area of focus is uterine fibroids. Brother Long believes Qigong offers possibilities for the human body that many people have never been taught to consider, and he wants people to have the opportunity to experience these practices for themselves.</p><p>Today, he calls himself <strong>Brother Long the Fibroid Fixer</strong>. Fibroids may be where the work begins, but for Brother Long, they are not where it ends. His larger mission is to share the ancient wisdom he has spent nearly two decades studying, seeking and practicing, and to help bring that knowledge back into the community.</p></details></div><a class=\"text-link\" href=\"mailto:TheFibroidFixer@gmail.com\">Get in touch by email <span aria-hidden=\"true\">↗</span></a></div>\n      </div>\n    <div class=\"section-wave wave-bottom\" aria-hidden=\"true\"><svg viewBox=\"0 0 1440 100\" preserveAspectRatio=\"none\"><path d=\"M0 35C250 98 440 -12 720 30S1200 96 1440 30V100H0Z\"/></svg></div></section>\n\n    <section id=\"foundations\" class=\"foundations section-space wrap\">\n      <div class=\"section-intro\"><div><p class=\"eyebrow\">04 / Teaching foundations</p><h2>A closer look at<br> the bigger picture.</h2></div><p>Explore the teaching tools behind the program. These traditional diagrams offer three ways to explore relationships, rhythm, and balance. Select a diagram for a closer look.</p></div>\n      <div id=\"foundation-list\" class=\"foundation-list\"></div><p class=\"foundation-context\">Traditional teaching models presented for educational context.</p>\n    </section>\n\n    <!-- Approved testimonials can be added to content.js. The whole section,\n         including navigation, remains hidden until real quotes are supplied. -->\n    <section id=\"testimonials\" class=\"testimonials section-space\" hidden><div class=\"wrap\"><p class=\"eyebrow\">Participant experiences</p><h2>In their own words.</h2><div id=\"testimonial-list\"></div></div></section>\n\n    <section id=\"classes\" class=\"classes section-space\">\n      <div class=\"wrap classes-grid\">\n        <div><p class=\"eyebrow\">05 / Live classes</p><h2>Make space for<br> a new beginning.</h2><p class=\"classes-description\">Learn with Brother Long from wherever you are. Live online classes bring the practice into your own space.</p><div class=\"class-format\"><span class=\"video-icon\" aria-hidden=\"true\"></span><div><strong>Live on Zoom</strong><span>Zoom information provided after registration.</span></div></div></div>\n        <div id=\"class-card\" class=\"class-card\"></div>\n      </div>\n    <div class=\"section-wave wave-bottom\" aria-hidden=\"true\"><svg viewBox=\"0 0 1440 100\" preserveAspectRatio=\"none\"><path d=\"M0 35C250 98 440 -12 720 30S1200 96 1440 30V100H0Z\"/></svg></div></section>\n\n    <section id=\"newsletter\" class=\"newsletter section-space wrap\" aria-labelledby=\"newsletter-heading\">\n      <div><p class=\"eyebrow\">Stay in the loop</p><h2 id=\"newsletter-heading\">A little inspiration.<br> A heads-up on what’s next.</h2><p>Future class updates and program news.</p></div>\n      <form id=\"newsletter-form\" class=\"newsletter-form\" novalidate>\n        <label for=\"newsletter-email\">Email address</label><div class=\"input-row\"><input id=\"newsletter-email\" type=\"email\" autocomplete=\"email\" placeholder=\"you@example.com\" aria-describedby=\"newsletter-help newsletter-status\" required><button class=\"button button-navy\" type=\"submit\">Sign up <span aria-hidden=\"true\">↗</span></button></div>\n        <p id=\"newsletter-help\" class=\"form-help\">Class updates and program news only. Unsubscribe anytime.</p><p id=\"newsletter-status\" role=\"status\" aria-live=\"polite\"></p>\n      </form>\n    </section>\n\n    <section id=\"faq\" class=\"faq section-space\">\n      <div class=\"wrap faq-grid\"><div><p class=\"eyebrow\">06 / A few useful answers</p><h2>Before<br> you begin.</h2><p>Have another question?</p><a class=\"text-link email-link\" href=\"mailto:TheFibroidFixer@gmail.com\">TheFibroidFixer@gmail.com <span aria-hidden=\"true\">↗</span></a></div><div id=\"faq-list\" class=\"faq-list\"></div></div>\n    </section>\n\n    <section class=\"closing section-space\" aria-labelledby=\"closing-heading\"><div class=\"section-wave wave-top\" aria-hidden=\"true\"><svg viewBox=\"0 0 1440 100\" preserveAspectRatio=\"none\"><path d=\"M0 35C250 98 440 -12 720 30S1200 96 1440 30V100H0Z\"/></svg></div><div class=\"closing-sun\" aria-hidden=\"true\"></div><div class=\"wrap closing-content\"><p class=\"eyebrow\">Your next horizon</p><h2 id=\"closing-heading\">Ready to begin?</h2><p>Get to know the practice. Take your next step.</p><a class=\"button button-navy\" href=\"#classes\">Register for a Class <span aria-hidden=\"true\">↗</span></a><p class=\"closing-note\">Class schedule and registration coming soon.</p></div></section>\n  </main>\n\n  <footer class=\"footer\"><div class=\"wrap\"><div class=\"footer-top\"><a class=\"wordmark\" href=\"#home\">The Fibroid Fixer<span class=\"wordmark-dot\" aria-hidden=\"true\">.</span></a><a class=\"email-link\" href=\"mailto:TheFibroidFixer@gmail.com\">TheFibroidFixer@gmail.com <span aria-hidden=\"true\">↗</span></a></div><div class=\"footer-middle\"><p>Healing still happens.</p><nav aria-label=\"Footer navigation\"><a href=\"#home\">Home</a><a href=\"#program\">Program</a><a href=\"#about\">About</a><a href=\"#classes\">Classes</a><a href=\"#faq\">FAQ</a></nav></div><div class=\"disclaimer\"><h2>Health disclaimer</h2><p>The Fibroid Fixer Program offers Qigong-based education and practices intended to support health and well-being. The program is not a substitute for medical diagnosis, treatment or advice from a licensed healthcare provider.</p><p>Individual experiences and results may vary. Participants are encouraged to continue working with their healthcare providers regarding any medical concerns or treatment decisions.</p></div><div class=\"footer-bottom\"><span>© 2026 The Fibroid Fixer. All rights reserved.</span><span>Privacy Policy &amp; Terms: to be added.</span></div></div></footer>\n";
